import pandas as pd, json, collections, re, hashlib, math, statistics
for path in ['taco_verl/train.parquet','taco_verl/test.parquet']:
 df=pd.read_parquet(path)
 print('\n===',path,len(df))
 issues=[]
 for i,row in df.iterrows():
  ex=row['extra_info']; rm=row['reward_model']; p=row['prompt']
  if not isinstance(ex,dict): issues.append((i,'extra_type',type(ex))); continue
  pid=ex.get('problem_id'); gt=rm.get('ground_truth') if isinstance(rm,dict) else None
  try: obj=json.loads(gt)
  except Exception as e: issues.append((i,'gt_json',repr(e))); continue
  ins=obj.get('inputs'); outs=obj.get('outputs')
  if not isinstance(ins,list) or not isinstance(outs,list): issues.append((i,'gt_io_type',type(ins),type(outs)))
  if len(ins or []) != len(outs or []): issues.append((i,'io_len',len(ins or []),len(outs or [])))
  if ex.get('n_tests') != len(ins or []): issues.append((i,'n_tests',ex.get('n_tests'),len(ins or [])))
  if ex.get('split') not in ('train','test'): issues.append((i,'split',ex.get('split')))
  if not isinstance(p,list) or len(p)!=1 or p[0].get('role')!='user': issues.append((i,'promptshape',p))
  else:
   c=p[0].get('content','')
   if 'QUESTION:' not in c or 'ANSWER:' not in c or 'Use Standard Input format' not in c: issues.append((i,'template',c[:100]))
   # answer should be final marker
   if c.count('QUESTION:')!=1 or c.count('ANSWER:')!=1: issues.append((i,'templcount',c.count('QUESTION:'),c.count('ANSWER:')))
 print('issues',len(issues)); print(*issues[:100],sep='\n')
 # per fields
 for k in ['code_type','fn_name','split','problem_id']:
  c=collections.Counter((x if not isinstance(x,(dict,list)) else str(x)) for x in df.extra_info.map(lambda x:x.get(k) if isinstance(x,dict) else None))
  print(k,c.most_common(20), 'nunique',len(c))
 # unique answer objects, input output hash etc
 print('styles',collections.Counter(str(x.get('style')) for x in df.reward_model))
 # code question type signals
 qs=[]
 for p in df.prompt:
  c=p[0]['content']; q=c.split('QUESTION:',1)[1].split('\nANSWER:',1)[0]; qs.append(q)
 print('question lengths',min(map(len,qs)),statistics.mean(map(len,qs)),max(map(len,qs)))
 print('groundtruth lengths',min(map(len,df.reward_model.map(lambda x:x['ground_truth']))),statistics.mean(map(len,df.reward_model.map(lambda x:x['ground_truth']))),max(map(len,df.reward_model.map(lambda x:x['ground_truth']))))
PY
