const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
p=Path('logs').glob('*.log'); p=next(p)
ls=p.read_text(errors='replace').splitlines()
print('lines',len(ls))
for l in ls:
 if 'step:' in l and 'global_seqlen' in l:
  # print compact selected fields
  import re
  keys=['training/global_step','critic/score/mean','response_length/mean','response_length/max','response_length/clip_ratio','response/aborted_ratio','timing_s/step','perf/throughput','actor/loss','actor/entropy','actor/grad_norm']
  d={}
  for k in keys:
   m=re.search(re.escape(k)+r':([^ ]+)',l)
   if m:d[k]=m.group(1)
  print(d)
print('validation markers')
for i,l in enumerate(ls):
 if 'val' in l.lower() or 'validation' in l.lower():
  if any(s in l for s in ['step:','validation','val/core','val/']): print(i,l[:1000])
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000});
text(r.output);

