  p=row['prompt']; ex=row['extra_info']; rm=row['reward_model']
  # normalize prompt
  if isinstance(p,np.ndarray): p=p.tolist()
  if not isinstance(p,list) or len(p)!=1 or not isinstance(p[0],dict): issues.append((i,'prompt_shape',type(p),repr(p)[:100])); continue
  msg=p[0]
  if msg.get('role')!='user': issues.append((i,'role',msg.get('role')))
  c=msg.get('content')
  if not isinstance(c,str): issues.append((i,'content_type',type(c))); continue
  if c.count('QUESTION:')!=1 or c.count('ANSWER:')!=1 or 'Use Standard Input format' not in c: issues.append((i,'template',c.count('QUESTION:'),c.count('ANSWER:'),'Use Standard Input format' in c))
  if not isinstance(ex,dict): issues.append((i,'extra_type',type(ex))); continue
  if not isinstance(rm,dict) or not isinstance(rm.get('ground_truth'),str): issues.append((i,'rm_type',repr(rm)[:100])); continue
  try: gt=json.loads(rm['ground_truth'])
  except Exception as e: issues.append((i,'gt_json',repr(e))); continue
  if not isinstance(gt,dict): issues.append((i,'gt_not_dict')); continue
  ins,outs=gt.get('inputs'),gt.get('outputs')
