# Map dump input to train/test prompt and summarize score/pass/output len by pid across all train rollout dumps.
tr=pd.read_parquet('taco_verl/train.parquet');te=pd.read_parquet('taco_verl/test.parquet')
def dec(x):
 if isinstance(x,(dict,list)):return x
 if isinstance(x,np.ndarray):return x.tolist()
 return json.loads(x)
def prompt(r):return dec(r.prompt)[0]['content']
# dump input starts user\n<raw prompt>\n\nassistant\n; recover between user\n and \n\nassistant
mp={prompt(r): (f'train{dec(r.extra_info)["index"]}',dec(r.extra_info)['problem_id'],i) for i,r in tr.iterrows()}
mp.update({prompt(r):(f'test{dec(r.extra_info)["index"]}',dec(r.extra_info)['problem_id'],i) for i,r in te.iterrows()})
agg=collections.defaultdict(lambda:{'n':0,'score':[],'pass':[],'out':[],'steps':[],'found':0})
miss=0
for p in glob.glob('rollout_data/*.jsonl'):
 for line in open(p):
  x=json.loads(line); inp=x['input'];
  # exact prompt extraction
  if inp.startswith('user\n'): k=inp[len('user\n'):].split('\n\nassistant\n',1)[0]
  else:k=inp
  m=mp.get(k)
  if not m:
   # maybe input has assistant trailing differences
   miss+=1; continue
  pid=m[1];a=agg[pid];a['n']+=1;a['score'].append(x.get('score'));a['pass'].append(x.get('pass_rate'));a['out'].append(len(x.get('output','')));a['steps'].append(x.get('step'));a['found']=m[2]
print('dump records',sum(a['n'] for a in agg.values()),'miss',miss,'pids',len(agg))
rows=[]
for pid,a in agg.items():rows.append((pid,a['n'],sum(a['score'])/len(a['score']),sum(a['pass'])/len(a['pass']),statistics.mean(a['out']),max(a['out']),a['found'],min(a['steps']),max(a['steps'])))
print('lowest score',sorted(rows,key=lambda x:x[2])[:40]);print('lowest pass',sorted(rows,key=lambda x:x[3])[:40]);print('largest outputs',sorted(rows,key=lambda x:x[5],reverse=True)[:40]);print('high mean outputs',sorted(rows,key=lambda x:x[4],reverse=True)[:40])
