const r = await tools.exec_command({cmd:"python3 - <<'PY'
import pyarrow.parquet as pq, json, hashlib, collections, statistics, re, math, os
for fn in ['taco_verl/train.parquet','taco_verl/test.parquet']:
 rows=pq.read_table(fn).to_pylist()
 print('\n===',fn,len(rows),'===')
 print('data_source',collections.Counter(r['data_source'] for r in rows))
 print('ability',collections.Counter(r['ability'] for r in rows))
 print('split',collections.Counter(r['extra_info']['split'] for r in rows))
 print('code_type',collections.Counter(r['extra_info']['code_type'] for r in rows))
 print('styles',collections.Counter(r['reward_model']['style'] for r in rows))
 print('fn_name',collections.Counter(str(r['extra_info']['fn_name']) for r in rows).most_common(10))
 ids=[r['extra_info']['problem_id'] for r in rows]; print('ids unique',len(set(ids)),'dups',[(x,n) for x,n in collections.Counter(ids).items() if n>1][:20])
 ps=[]
 for r in rows:
  p=r['prompt']
  # pyarrow conversion list dict
  txt='\n'.join(m['content'] for m in p)
  ps.append(txt)
 print('prompt unique',len(set(ps)),'dups',[(i,n) for i,n in collections.Counter(ps).items() if n>1][:5])
 print('prompt chars min/max/mean',min(map(len,ps)),max(map(len,ps)),statistics.mean(map(len,ps)))
 print('prompt_tokens min/max/mean',min(r['extra_info']['prompt_tokens'] for r in rows),max(r['extra_info']['prompt_tokens'] for r in rows),statistics.mean(r['extra_info']['prompt_tokens'] for r in rows))
 print('n_tests min/max/mean',min(r['extra_info']['n_tests'] for r in rows),max(r['extra_info']['n_tests'] for r in rows),statistics.mean(r['extra_info']['n_tests'] for r in rows))
 # prompt format anomalies
 for i,r in enumerate(rows):
  txt='\n'.join(m['content'] for m in r['prompt'])
  issues=[]
  if len(r['prompt'])!=1: issues.append('prompt_len='+str(len(r['prompt'])))
  if not txt.startswith('Please write a python program'): issues.append('prefix')
  if 'QUESTION:' not in txt or 'ANSWER:' not in txt: issues.append('markers')
  gt=r['reward_model']['ground_truth']
  try:
   d=json.loads(gt)
   if not isinstance(d,dict) or 'inputs' not in d or 'outputs' not in d: issues.append('gt_keys')
   if len(d.get('inputs',[])) != len(d.get('outputs',[])): issues.append('gt_len')
  except Exception as e: issues.append('gt_json')
  if issues: print('issue',i,r['extra_info']['problem_id'],issues,'prompt',txt[:200])
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":30000});
text(r.output);

