const r = await tools.exec_command({cmd:"python3 - <<'PY'
import pyarrow.parquet as pq, json, collections, statistics, re, math
for fn in ['taco_verl/train.parquet','taco_verl/test.parquet']:
 rows=pq.read_table(fn).to_pylist(); print('\n===',fn,'===')
 fields=collections.Counter(); weird=[]
 for i,r in enumerate(rows):
  gt=json.loads(r['reward_model']['ground_truth'])
  keys=tuple(sorted(gt)); fields[keys]+=1
  lens={k:len(v) if hasattr(v,'__len__') else None for k,v in gt.items()}
  # per output weird
  ins=gt.get('inputs',[]); outs=gt.get('outputs',[])
  if len(ins)!=len(outs): weird.append((i,'length',len(ins),len(outs)))
  if not ins: weird.append((i,'empty'))
  # output shape/values summary
  if isinstance(outs,list):
   for j,o in enumerate(outs):
    if not isinstance(o,str): weird.append((i,'outtype',j,type(o).__name__))
  # ground truth nested etc
  if 'fn_name' in gt and r['extra_info']['fn_name'] is None: pass
 print('gt key sets',fields,'weird',len(weird),weird[:20])
 # length distributions and extreme rows
 for k in ['inputs','outputs']:
  vals=[]
  for i,r in enumerate(rows):
   gt=json.loads(r['reward_model']['ground_truth']); vals.append((len(gt.get(k,[])),i,r['extra_info']['problem_id']))
  print(k,'min',min(v[0] for v in vals),'max',max(v[0] for v in vals),'mean',statistics.mean(v[0] for v in vals))
  print('top',sorted(vals,reverse=True)[:10]); print('bottom',sorted(vals)[:10])
 # output/input content type stats
 for k in ['inputs','outputs']:
  chars=[]; empties=[]; control=[]
  for i,r in enumerate(rows):
   gt=json.loads(r['reward_model']['ground_truth'])
   for j,x in enumerate(gt.get(k,[])):
    if isinstance(x,str):
     chars.append(len(x));
     if not x.strip(): empties.append((i,j))
     if any(ord(c)<9 or (13<ord(c)<32) for c in x): control.append((i,j,repr(x[:100])))
  print(k,'chars min/max/mean',min(chars),max(chars),statistics.mean(chars),'empty',len(empties),'control',len(control),control[:5])
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":30000});
