const cmds = [
 ["ls", "ls -la /workspace; find /workspace -maxdepth 2 -type f -printf '%p %s bytes\n' | sort | sed -n '1,160p'"],
 ["log_steps", "python3 - <<'PY'
import re, pathlib, json
p=pathlib.Path('/workspace/logs').glob('*.log'); p=next(p)
s=p.read_text(errors='replace')
print('chars',len(s),'lines',s.count('\n'))
# each actual metric line starts step:N -
lines=[x for x in s.splitlines() if 'step:' in x and ' - ' in x]
print('metric lines',len(lines))
for line in lines:
 m=re.search(r'step:(\d+)',line)
 if m:
  vals={k:float(v) for k,v in re.findall(r'(val-core/taco/acc/mean@1|val-aux/taco/pass_rate/mean@1|critic/rewards/mean|response_length/mean|response_length/clip_ratio|actor/entropy|actor/kl_loss|actor/grad_norm|perf/time_per_step):([-+0-9.eE]+)',line)}
  print(m.group(1),vals)
PY"],
 ["val_dump", "python3 - <<'PY'
import json,glob,os,collections,statistics
for d in ['validation_data','rollout_data']:
 print('\n',d)
 for f in sorted(glob.glob('/workspace/'+d+'/*.jsonl'),key=lambda x:int(os.path.basename(x).split('.')[0])):
  rows=[]
  with open(f) as h:
   for line in h:
    try: rows.append(json.loads(line))
    except Exception as e: print('bad',f,e)
  if not rows: continue
  scores=[r.get('score',r.get('reward')) for r in rows]
  acc=[r.get('acc') for r in rows if r.get('acc') is not None]
  pr=[r.get('pass_rate') for r in rows if r.get('pass_rate') is not None]
  steps=set(r.get('step') for r in rows)
  print(os.path.basename(f),len(rows),'step',steps,'score_mean',statistics.mean(scores) if scores else None,'acc_mean',statistics.mean(acc) if acc else None,'pass_mean',statistics.mean(pr) if pr else None,'score_dist',collections.Counter(scores).most_common(4))
PY"],
 ["parquet_summary", "python3 - <<'PY'
import pandas as pd, json, hashlib, collections, re
for f in ['/workspace/taco_verl/train.parquet','/workspace/taco_verl/test.parquet']:
 df=pd.read_parquet(f)
 print('\nFILE',f,'shape',df.shape,'cols',df.columns.tolist())
 for c in df.columns:
  vals=df[c].tolist();
  try: uniq=len({json.dumps(v,sort_keys=True,default=str) for v in vals})
  except: uniq='?'
  print(c,'null',sum(x is None for x in vals),'uniq_json',uniq,'types',collections.Counter(type(x).__name__ for x in vals).most_common())
 print('extra sample',df.extra_info.iloc[0])
 print('prompt sample',repr(df.prompt.iloc[0])[:500])
 print('row hashes first',hashlib.sha256(pd.util.hash_pandas_object(df,index=True).values.tobytes()).hexdigest())
PY"]
];
